{
  "name": "威尔创 360 网络分析仪",
  "name_en": "Wiltron 360 Network Analyzer",
  "manufacturer": "Wiltron",
  "description": "用于射频/微波测试的网络分析仪，可进行频率扫描并读取横轴、纵轴及复数迹线数据，适合器件频率响应表征与分析。",
  "description_en": "An RF/microwave network analyzer used for frequency sweeps and acquisition of x-axis, y-axis, and complex trace data for device response characterization and analysis.",
  "actions": [
    {
      "action_name": "auto-xaxis",
      "description": "获取当前扫描的横轴数据，通常为频率点。",
      "description_en": "Get the current sweep x-axis data, typically frequency points."
    },
    {
      "action_name": "auto-yaxis",
      "description": "获取当前迹线的纵轴测量数据。",
      "description_en": "Get the y-axis measurement data of the current trace."
    },
    {
      "action_name": "auto-trace",
      "description": "获取指定或当前迹线的数据，可包含与频率轴对应的复数响应。",
      "description_en": "Get the specified or current trace data, including complex response aligned with the frequency axis."
    },
    {
      "action_name": "auto-traces",
      "description": "获取全部可用迹线的数据。",
      "description_en": "Get data for all available traces."
    },
    {
      "action_name": "auto-select",
      "description": "选择要操作或读取的迹线。",
      "description_en": "Select the trace to operate on or read."
    },
    {
      "action_name": "auto-frequency",
      "description": "获取或设置频率扫描相关配置。",
      "description_en": "Get or set the frequency sweep configuration."
    },
    {
      "action_name": "auto-points",
      "description": "获取扫描点数。",
      "description_en": "Get the number of sweep points."
    },
    {
      "action_name": "auto-arange",
      "description": "执行自动量程或自动范围调整。",
      "description_en": "Perform auto-ranging or automatic range adjustment."
    },
    {
      "action_name": "auto-IDN",
      "description": "读取仪器身份信息。",
      "description_en": "Read the instrument identification information."
    }
  ],
  "tag_hints": [
    "network analyzer",
    "RF measurement",
    "microwave characterization",
    "frequency sweep",
    "complex trace data",
    "trace acquisition"
  ]
}

